insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', 'F', ARRAY['Retelling is when I tell what happened in the text','Some texts need to be retold in order and some do not (Fiction vs non-fiction)','Pictures and words in the text can help me answer questions.'], ARRAY['I can look back at the pictures and words to retell 1-2 pieces of important information','I can look back at the pictures and words in the book to retell what happened.','I can retell the beginning, problem and solution of a text.','I can retell the events/steps in order']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '1', ARRAY['Every text has a purpose it was written for.','Summarising is when we tell the most important information from a text.','Each genre has unique features. These features are important when summarising and locating specific information.'], ARRAY['I can identify the purpose for reading.','I can explain what information is important within the text.','I can use the sequence of a text to help me locate information.','I can use the features of a non-fiction text to locate information, including the contents page, subheadings, glossary, captions, pictures and diagrams.','I can use the features of fiction texts to locate information, chronological order, plot, events, problems, solutions and characters.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '2', ARRAY['Texts are created for a specific purpose and audience','Summarising is when we retell the most important information from within a text.','Each genre has unique features. These features are important when summarising and locating specific information.','The main idea of the text is most important point/part the author wants us to understand'], ARRAY['I can identify the purpose and audience of different types of texts','I can explain what information is important within the text.','I can summarise a text in the correct sequence.','I can use the features of a non-fiction text to locate information, including the contents page, subheadings, glossary, captions, pictures and diagrams.','I can use the features of fiction texts to locate key information, chronological order, plot, events, problems, solutions and characters.','I can identify and justify what the main idea of the text is.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '3', ARRAY['Images and sounds within a text enhance our understanding of texts.','Summaries are more precise when we retell only the most important ideas, events or details'], ARRAY['I can identify different types of images used within a text such as photographs, diagrams, maps, labels etc).','I can explain how these images helped us understand the text.','I can identify important and un-important ideas, events or details']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '4', ARRAY['The main and supporting ideas of a text help us identify and elaborate on our understanding of the text.','Summaries can include a climax, theme and lesson.','Author''s use dialogue to help us understand a character.','Scanning or skimming ahead allows us to search for information more efficiently.'], ARRAY['identifying moments in the plot where characters are faced with choices, and commenting on how the author makes the reader care about their decisions and the consequences','I can identify the main idea of the text and their supporting details.','I can identify what is learnt about a character through dialogue such as their likes, dislikes or personal qualities','I can include the climate, lesson and theme of the text when summarising.','I can scan for information using key words and graphics.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '5', ARRAY['Certain sections of a text can be more significant to summarise to help us understand the characters, plot or message of a text.','The main idea of the text is the central point or most important thought the author wants to convey about a topic.','Texts on the same topic may have similarities and differences in ideas.','Information about a text can be summarised from several sources.','Texts can represent details and information about historical, cultural and social contexts. Including texts by Aboriginal and Torres Strait Islander authors and those from a range of backgrounds.'], ARRAY['I can summarise the ideas and information in the text along with the main idea.','I can explain how the ideas of a text are similar or different.','I can select a section of the text and summarise it to reflect my understanding of the characters, plot and message.','I can locate the main ideas from different texts and use them to summarise information about a topic.','I can identify aspects of a text (images, symbols, dialogue, character description) that are representing details and information about historical, cultural or social context.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('summarising', '6', ARRAY['A range of resources can be utilised to search for information.','Embedded clauses can expand the variety of complex sentences to elaborate, extend and explain ideas.','Summaries need to be of concise relate important information, often with relevant opinions and evidence which reflect the overall message or theme of the text.','Information in texts have different hierarchies ranging from most to least important'], ARRAY['I can identify the overall message or theme of the texts','I can summarise the texts using relevant information, arguments or opinions which support the overall message or meaning of the text.','I can investigate how the choice of conjunctions enables the construction of complex sentences to extend, elaborate on and explain ideas, for example ''The town that was flooded suffered extensive damage.''','I can identify information from most to least important','I can use a range of resource form the text to locate specifi information e.g diagrams, sideboards, hyperlinks etc.']);
