insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('determining_importance', '4', ARRAY['The main and supporting ideas of a text help us identify and elaborate on our understanding of the text.','Summaries can include a climax, theme and lesson.','Author''s use dialogue to help us understand a character.','Scanning or skimming ahead allows us to search for information more efficiently.'], ARRAY['identifying moments in the plot where characters are faced with choices, and commenting on how the author makes the reader care about their decisions and the consequences','I can identify the main idea of the text and their supporting details.','I can identify what is learnt about a character through dialogue such as their likes, dislikes or personal qualities','I can include the climate, lesson and theme of the text when summarising.','I can scan for information using key words and graphics.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('determining_importance', '5', ARRAY['Certain sections of a text can be more significant to summarise to help us understand the characters, plot or message of a text.','The main idea of the text is the central point or most important thought the author wants to convey about a topic.','Texts on the same topic may have similarities and differences in ideas.','Information about a text can be summarised from several sources.','Texts can represent details and information about historical, cultural and social contexts. Including texts by Aboriginal and Torres Strait Islander authors and those from a range of backgrounds.'], ARRAY['I can summarise the ideas and information in the text along with the main idea.','I can explain how the ideas of a text are similar or different.','I can select a section of the text and summarise it to reflect my understanding of the characters, plot and message.','I can locate the main ideas from different texts and use them to summarise information about a topic.','I can identify aspects of a text (images, symbols, dialogue, character description) that are representing details and information about historical, cultural or social context.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('determining_importance', '6', ARRAY['A range of resources can be utilised to search for information.','Embedded clauses can expand the variety of complex sentences to elaborate, extend and explain ideas.','Summaries need to be of concise relate important information, often with relevant opinions and evidence which reflect the overall message or theme of the text.','Information in texts have different hierarchies ranging from most to least important'], ARRAY['I can identify the overall message or theme of the texts','I can summarise the texts using relevant information, arguments or opinions which support the overall message or meaning of the text.','I can investigate how the choice of conjunctions enables the construction of complex sentences to extend, elaborate on and explain ideas, for example ''The town that was flooded suffered extensive damage.''','I can identify information from most to least important','I can use a range of resource form the text to locate specifi information e.g diagrams, sideboards, hyperlinks etc.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', 'F', ARRAY['Predicting is when we think about what might happen in the book.','Prior knowledge can be used to help me predict and make connections to the text,','Texts often allow us to learn something new.','Clues within a text are needed to infer the emotions of a character'], ARRAY['I can use the title and front cover to predict what might happen in the text','I can predict the problem and solution of the text using what has already happened in the text.','I can identify how the book reminds me of something in my own life.','I can explain what I already knew about the topic before reading it.','I can explain what I learnt about the topic from reading the text.','I can infer the emotions of a character using pictures and words (happy, sad, angry, excited, tired).']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '1', ARRAY['Each genre has unique features. These features are important when making predictions. (predicting)','Predicting is when we make an educated guess about what might happen within the text. (predicting)','Inferring is when we work out what the author doesn''t exactly say.'], ARRAY['I can use many clues to help me predict what might happen within the text (title, front cover pictures, blurb, prior knowledge, text structure, books by the same author). (predicting)','I can change my predictions as I gain more information when reading. (predicting)','I can infer character feelings using text clues such as pictures and words.','I can make connections between a text and my own life.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '2', ARRAY['That synthesis is when we use our prior knowledge and the text to build deeper understandings. (Synthesising)','Predicting likely vocabulary in the text helps us tune in to the topic or ideas of the text.','Using our prior knowledge and text evidence helps us more accurate predictions.'], ARRAY['I can identify my prior knowledge about the text and what is new to me. (synthesising)','I can identify how the new knowledge developed my thinking. (synthesising)','I can predict vocabulary words I might encounter when reading my text.','I can use my prior knowledge and text evidence to make, confirm or modify predictions.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '3', ARRAY['Knowledge of other texts can help us make predictions about similar texts.','Chapter headings, sub-heading or tabs can foreshadow a storyline or information to come.','Synthesising helps us develop new understandings of a topic or subject.','Using a range of text clues can help me make predictions and inferences.','The message or moral of a text can help us learn lessons to use in real life.'], ARRAY['I can use the chapter heading or sub-heading to predict the likely storyline or information I will encounter','I can explain how the sounds in a digital texts helped us understand the text.','I can use what I already know about a similar text to make predictions.','I can discuss what I already knew about the topic','I can identify what was new information and how I now better understand my topic/subject.','I can use a range of text clues to make predictions/inferences including pictures, graphics, past storyline,','I can identify the author''s message of a text using a range of text clues','I can infer a character''s traits using different clues.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '4', ARRAY['Author''s use a range of devices to explain a character.','The message of the text can help people learn lessons to use in their own lives.','Characters develop traits based on their experiences.','Connections can help us develop a deeper understanding of texts'], ARRAY['I can identify the message of the text.','I can discuss how the message of the text is applicable to people''s own lives.','I can infer the causes of the characters traits.','I can identify the point of view in the text.','I can describe the character''s perspective and how it changes throughout the text.','I can make connections (text to text and text to world) to compare perspectives, ideas, characterization and literacy devices.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '5', ARRAY['Author''s encourage us to ask questions about the beliefs and actions of characters.','Texts written in the past can be identified by their ideas, vocabulary or expressions.','The tone of the text helps us to infer characters or author''s opinions or attitudes.'], ARRAY['I can discuss how characters could behave differently and how the author supported or challenged our belief about the characters.','I can discuss texts written by Aboriginal and Torres Strait Islander authors about events that shaped or impacted their lives and make inferences about their feelings.','I can make inferences about characters'' motives, themes, and underlying messages.','I can infer the time and place in which a text was written.','I can compare the ideas, vocabulary and expressions of texts written in the past with those written today.','I can identify the tone of the text and justify this with text evidence.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('predicting', '6', ARRAY['Knowledge of literary works can assist in making accurate predictions.','Narrative texts have many variations in their plot structures','Knowledge of different disciplines e.g science and technology), allow us to better understand texts.','Relationships among characters can be inferred using a range of sources.','Texts in many genres give us new insights into cultures of historical times.'], ARRAY['I can use my prior knowledge of genre, text structure and purpose to predict information, arguments, evidence and plotlines of texts.','I can predict if texts will contain specific literacy features such as plot twists, flashbacks, flashforwards or foreshadowing.','I can discuss my prior knowledge on a specific subject and how it relates to the text I have read.','I can identify the relationship between the characters and how these change based upon plots and interpretations.','I can explain what cultural and historical insights the text has provided to us and how.']);
insert into reading_strategy_detail (strategy_slug, year_level, ku_verbatim, ks_verbatim) values ('making_connections', 'F', ARRAY['Predicting is when we think about what might happen in the book.','Prior knowledge can be used to help me predict and make connections to the text,','Texts often allow us to learn something new.','Clues within a text are needed to infer the emotions of a character'], ARRAY['I can use the title and front cover to predict what might happen in the text','I can predict the problem and solution of the text using what has already happened in the text.','I can identify how the book reminds me of something in my own life.','I can explain what I already knew about the topic before reading it.','I can explain what I learnt about the topic from reading the text.','I can infer the emotions of a character using pictures and words (happy, sad, angry, excited, tired).']);
